// La fila sale de la MySQL (nodo anterior): el webhook solo trae el id.
// Sin fila = el aviso ya se mandó, es viejo o la persona ya no tiene ese rol.
const a = $input.first() && $input.first().json;
if (!a || !a.id || !a.email) return [];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
let grupos = [];
try { grupos = JSON.parse(a.secciones_json || '[]'); } catch (e) { grupos = []; }

const url = String(a.url_panel || 'https://panel.supricom.com.ve');
const rol = a.rol_nombre || a.rol;
const nombre = String(a.nombre || '').trim().split(/\s+/)[0] || '';

const intro = a.rol_anterior
  ? 'Tu rol en el <b>Panel SUPRICOM</b> cambió de <b>' + esc(a.rol_anterior) + '</b> a <b>' + esc(rol) + '</b>.'
  : 'Ya tienes acceso al <b>Panel SUPRICOM</b> con el rol <b>' + esc(rol) + '</b>.';

const secciones = grupos.map((g) =>
  '<p style="margin:16px 0 6px;font-weight:bold;color:#1e3a8a">' + esc(g.area) + '</p>' +
  '<ul style="margin:0;padding-left:20px">' +
  (g.secciones || []).map((s) => '<li style="margin:3px 0"><b>' + esc(s.nombre) + '</b>: ' + esc(s.detalle) + '</li>').join('') +
  '</ul>'
).join('');

const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#111;max-width:640px">' +
  '<p>Hola' + (nombre ? ' ' + esc(nombre) : '') + ',</p>' +
  '<p>' + intro + '</p>' +
  '<div style="border:1px solid #e5e7eb;border-radius:8px;padding:14px 16px;margin:16px 0;background:#f9fafb">' +
    '<p style="margin:0 0 8px"><b>Dirección del panel:</b> <a href="' + esc(url) + '">' + esc(url) + '</a></p>' +
    '<p style="margin:0 0 8px"><b>Tu rol:</b> ' + esc(rol) + '</p>' +
    '<p style="margin:0"><b>Cómo entrar:</b> con tu usuario y tu contraseña de <b>Odoo</b>, los mismos con los que entras a Odoo. ' +
    'Tu usuario es tu correo: <b>' + esc(a.email) + '</b>. El panel no tiene una contraseña aparte: si la olvidas o la cambias, se hace en Odoo.</p>' +
  '</div>' +
  '<p style="margin:20px 0"><a href="' + esc(url) + '" style="background:#1e3a8a;color:#fff;text-decoration:none;padding:10px 18px;border-radius:6px;display:inline-block">Entrar al panel</a></p>' +
  '<p style="margin:16px 0 4px;font-size:15px"><b>Qué puedes hacer con este rol</b></p>' +
  '<p style="margin:0 0 8px">' + esc(a.resumen) + '</p>' +
  (secciones ? '<p style="margin:8px 0 0">Estas son las secciones de tu menú:</p>' + secciones : '') +
  (a.rol_anterior ? '<p style="margin-top:20px">Si tenías el panel abierto, vuelve a iniciar sesión para ver tu nuevo menú.</p>' : '') +
  '<p style="margin-top:20px;color:#6b7280;font-size:12px">Este correo sale solo cuando se te asigna un rol en el panel' +
  (a.asignado_por ? ' (lo asignó ' + esc(a.asignado_por) + ')' : '') + '. Si no esperabas este acceso, avísale a tu supervisor.</p>' +
  '</div>';

return [{ json: { aviso_id: a.id, to: a.email, subject: 'Tu acceso al Panel SUPRICOM: rol ' + rol, html } }];
